SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
START TRANSACTION;

INSERT INTO catalog_versions (version, published_at, is_current, notes)
VALUES ('2026.08.15.songbook-lead-sheet', UTC_TIMESTAMP(), 1, 'Published Notion songbook lead sheet seed')
ON DUPLICATE KEY UPDATE
  published_at = VALUES(published_at),
  is_current = VALUES(is_current),
  notes = VALUES(notes);

SET @catalog_version_id := (SELECT id FROM catalog_versions WHERE version = '2026.08.15.songbook-lead-sheet' LIMIT 1);
UPDATE catalog_versions SET is_current = 0 WHERE id <> @catalog_version_id;
DELETE FROM songs WHERE catalog_version_id = @catalog_version_id;

